"use client"

import * as React from "react"
import type { ColumnDef } from "@tanstack/react-table"
import { format } from "date-fns"
import { SearchXIcon } from "lucide-react"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { setSearchParams, useSearchParams } from "@/hooks/use-url-state"
import {
  InfiniteTable,
  useCursorPages,
  type CursorPage,
} from "./infinite-table"
import { initials } from "@/lib/utils"

export type ActivityEvent = {
  id: string
  at: string
  level: "info" | "warning" | "error"
  event: string
  actor: string
  resource: string
  durationMs: number
}

const LEVEL = {
  info: { label: "Info", tone: "gray" },
  warning: { label: "Warning", tone: "amber" },
  error: { label: "Error", tone: "red" },
} as const
const EVENTS = [
  "invoice.paid",
  "member.invited",
  "project.created",
  "api_key.rotated",
  "deploy.succeeded",
  "webhook.failed",
  "login.succeeded",
  "export.started",
  "deploy.failed",
  "plan.changed",
]
const ACTORS = [
  "Renan Leonel",
  "Ana Souza",
  "João Silva",
  "Pedro Santos",
  "API",
]

// 1,240 deterministic events, newest first (same on server and client).
const ALL_EVENTS: ActivityEvent[] = Array.from({ length: 1240 }, (_, i) => {
  const event = EVENTS[(i * 7) % EVENTS.length]
  return {
    id: `evt_${(100_000 - i).toString(36)}`,
    at: new Date(Date.UTC(2026, 10, 13, 18, 0, 0) - i * 137_000).toISOString(),
    level: event.endsWith("failed")
      ? "error"
      : event === "api_key.rotated" || i % 13 === 0
        ? "warning"
        : "info",
    event,
    actor: ACTORS[(i * 3) % ACTORS.length],
    resource: `${event.split(".")[0]}_${((i * 7919) % 99_999).toString(36)}`,
    durationMs: 20 + ((i * 7907) % 2400),
  }
})

/**
 * Stands in for `GET /events?cursor=&limit=&level=`. The cursor is the last
 * event's id: stable while new events arrive, unlike an offset.
 */
async function listEvents({
  cursor,
  level,
  failOnce,
  delay = 700,
}: {
  cursor: string | null
  level: string | null
  delay?: number
  failOnce?: { current: boolean } | null
}): Promise<CursorPage<ActivityEvent>> {
  await new Promise((r) => setTimeout(r, delay))
  const matches = level
    ? ALL_EVENTS.filter((e) => e.level === level)
    : ALL_EVENTS
  const start = cursor ? matches.findIndex((e) => e.id === cursor) + 1 : 0
  // ?demo=error: the third page fails once, so Retry has something to do.
  if (failOnce && start >= 80) {
    failOnce.current = true
    throw new Error("Network error")
  }
  const items = matches.slice(start, start + 40)
  const end = start + items.length
  return {
    items,
    nextCursor: end < matches.length ? items.at(-1)!.id : null,
    total: matches.length,
  }
}

const columns: ColumnDef<ActivityEvent>[] = [
  {
    accessorKey: "at",
    header: "Time",
    meta: { skeleton: "w-28" },
    cell: ({ getValue }) => (
      <time
        dateTime={getValue<string>()}
        className="text-muted-foreground tabular-nums"
      >
        {format(new Date(getValue<string>()), "MMM d, HH:mm:ss")}
      </time>
    ),
  },
  {
    accessorKey: "level",
    header: "Level",
    meta: { skeleton: "w-14 rounded-full" },
    cell: ({ getValue }) => {
      const level = LEVEL[getValue<ActivityEvent["level"]>()]
      return <Badge tone={level.tone}>{level.label}</Badge>
    },
  },
  {
    accessorKey: "event",
    header: "Event",
    meta: { skeleton: "w-32" },
    cell: ({ getValue }) => (
      <span className="font-mono text-xs">{getValue<string>()}</span>
    ),
  },
  {
    accessorKey: "actor",
    header: "Actor",
    meta: { hideOnMobile: true, skeleton: "w-28" },
    cell: ({ getValue }) => {
      const name = getValue<string>()
      return (
        <span className="flex items-center gap-2">
          <Avatar size="sm" className="size-5">
            <AvatarFallback className="text-[10px]">
              {name === "API" ? "API" : initials(name)}
            </AvatarFallback>
          </Avatar>
          {name}
        </span>
      )
    },
  },
  {
    accessorKey: "resource",
    header: "Resource",
    meta: { hideOnMobile: true, skeleton: "w-24" },
    cell: ({ getValue }) => (
      <span className="font-mono text-xs text-muted-foreground">
        {getValue<string>()}
      </span>
    ),
  },
  {
    accessorKey: "durationMs",
    header: "Duration",
    meta: { align: "end", hideOnMobile: true, skeleton: "w-12" },
    cell: ({ getValue }) => `${getValue<number>().toLocaleString("en-US")} ms`,
  },
]

const LEVELS = [
  { value: "all", label: "All" },
  { value: "warning", label: "Warnings" },
  { value: "error", label: "Errors" },
]

/** Audit log with level filter (`?level=`), loaded 40 events at a time. */
export function ActivityLog({ className }: { className?: string }) {
  const params = useSearchParams()
  const level = params.get("level")
  return (
    <div className="flex min-h-0 flex-1 flex-col gap-3">
      <Tabs
        value={level ?? "all"}
        onValueChange={(v) =>
          setSearchParams({ level: v === "all" ? null : String(v) })
        }
      >
        <TabsList variant="segmented" aria-label="Level">
          {LEVELS.map((l) => (
            <TabsTrigger key={l.value} value={l.value}>
              {l.label}
            </TabsTrigger>
          ))}
        </TabsList>
      </Tabs>
      {/* A new filter is a new list: the key resets the loaded pages. */}
      <EventsList
        key={`${level}:${params.get("demo")}`}
        level={level}
        demo={params.get("demo")}
        className={className}
      />
    </div>
  )
}

function EventsList({
  level,
  demo,
  className,
}: {
  level: string | null
  demo: string | null
  className?: string
}) {
  // Read when fetching: the URL is only known after hydration.
  const failed = React.useRef(false)
  const fetchPage = React.useCallback(
    (cursor: string | null) =>
      demo === "empty"
        ? Promise.resolve({ items: [], nextCursor: null, total: 0 })
        : listEvents({
            cursor,
            level,
            failOnce: demo === "error" && !failed.current ? failed : null,
            delay: demo === "slow" ? 4000 : 700,
          }),
    [level, demo]
  )
  const query = useCursorPages(fetchPage)
  return (
    <InfiniteTable
      className={className}
      columns={columns}
      rows={query.rows}
      getRowId={(e) => e.id}
      total={query.total}
      hasNextPage={query.hasNextPage}
      isFetchingNextPage={query.isFetchingNextPage}
      isError={query.isError}
      fetchNextPage={query.fetchNextPage}
      noun={{ one: "event", other: "events" }}
      empty={
        <Empty className="rounded-lg py-16 shadow-border">
          <EmptyHeader>
            <EmptyMedia variant="icon">
              <SearchXIcon />
            </EmptyMedia>
            <EmptyTitle>No events match this filter</EmptyTitle>
            <EmptyDescription>
              Events show up here as your team works.
            </EmptyDescription>
          </EmptyHeader>
          <EmptyContent>
            <Button
              variant="outline"
              onClick={() => setSearchParams({ level: null, demo: null })}
            >
              Show all events
            </Button>
          </EmptyContent>
        </Empty>
      }
    />
  )
}

"use client"

import * as React from "react"
import {
  flexRender,
  getCoreRowModel,
  useReactTable,
  type ColumnDef,
} from "@tanstack/react-table"
import { useVirtualizer } from "@tanstack/react-virtual"
import { cn } from "cn"
import { ArrowUpIcon, RotateCwIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"

declare module "@tanstack/react-table" {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  interface ColumnMeta<TData, TValue> {
    /** Numbers align to the trailing edge (layout.md). */
    align?: "start" | "end"
    /** Hidden while the table is narrower than 42rem. */
    hideOnMobile?: boolean
    /** Skeleton bar width while loading, e.g. "w-24". */
    skeleton?: string
  }
}

export type CursorPage<T> = {
  items: T[]
  /** Opaque cursor for the next page; null on the last page. */
  nextCursor: string | null
  /** Total matches, when the API knows it cheaply. */
  total?: number
}

/**
 * Cursor pagination state with the same shape as TanStack Query's
 * `useInfiniteQuery` result, so `InfiniteTable` takes either. Reset it with a
 * `key` when the filters change. Already on TanStack Query? Use
 * `useInfiniteQuery({ queryKey, queryFn: ({ pageParam }) => fetchPage(pageParam),
 * initialPageParam: null, getNextPageParam: (p) => p.nextCursor })` instead.
 */
export function useCursorPages<T>(
  fetchPage: (cursor: string | null) => Promise<CursorPage<T>>
) {
  const [pages, setPages] = React.useState<CursorPage<T>[]>([])
  const [status, setStatus] = React.useState<"idle" | "fetching" | "error">(
    "idle"
  )
  // Guards double calls in the same tick (observer + click), before state lands.
  const inFlight = React.useRef(false)
  const last = pages.at(-1)
  const hasNextPage = !last || last.nextCursor !== null

  const fetchNextPage = React.useCallback(async () => {
    if (inFlight.current || !hasNextPage) return
    inFlight.current = true
    setStatus("fetching")
    try {
      const page = await fetchPage(last?.nextCursor ?? null)
      setPages((prev) => [...prev, page])
      setStatus("idle")
    } catch {
      setStatus("error")
    } finally {
      inFlight.current = false
    }
  }, [fetchPage, hasNextPage, last])

  return {
    data: { pages },
    rows: React.useMemo(() => pages.flatMap((p) => p.items), [pages]),
    total: last?.total,
    hasNextPage,
    isFetchingNextPage: status === "fetching",
    isPending: pages.length === 0 && status !== "error",
    isError: status === "error",
    fetchNextPage,
  }
}

/**
 * A table that loads the next page as you near the end (cursor pagination).
 * The header stays pinned; the next page starts loading 600px before the end,
 * so scrolling rarely waits. Loading, failure and the end each get a row, and a
 * "Load more" button stands in for scrolling (keyboard, screen readers). Give
 * it a height so it scrolls inside (`className="h-[600px]"`, or `flex-1 min-h-0`
 * inside `AppShellContent fill`).
 */
function InfiniteTable<TData>({
  columns,
  rows,
  getRowId,
  total,
  hasNextPage,
  isFetchingNextPage,
  isError,
  fetchNextPage,
  noun = { one: "item", other: "items" },
  empty,
  className,
}: {
  columns: ColumnDef<TData>[]
  rows: TData[]
  getRowId: (row: TData) => string
  total?: number
  hasNextPage: boolean
  isFetchingNextPage: boolean
  isError: boolean
  fetchNextPage: () => unknown
  noun?: { one: string; other: string }
  /** Shown when the first page comes back empty. */
  empty?: React.ReactNode
  className?: string
}) {
  // eslint-disable-next-line react-hooks/incompatible-library -- TanStack Table returns non-memoizable functions by design
  const table = useReactTable({
    data: rows,
    columns,
    getRowId,
    getCoreRowModel: getCoreRowModel(),
  })

  const scroller = React.useRef<HTMLDivElement>(null)
  const [scrolled, setScrolled] = React.useState(false)

  // Feeds grow without bound: render only the rows near the viewport, with
  // spacer rows standing in for the rest (keeps native table layout and the
  // pinned header).
  const tableRows = table.getRowModel().rows
  const virtualizer = useVirtualizer({
    count: tableRows.length,
    getScrollElement: () => scroller.current,
    estimateSize: () => ROW_HEIGHT,
    getItemKey: (i) => tableRows[i].id,
    overscan: 10,
    // Rows start under the pinned header.
    paddingStart: HEAD_HEIGHT,
    scrollPaddingStart: HEAD_HEIGHT,
  })
  const virtualRows = virtualizer.getVirtualItems()
  const padTop = (virtualRows[0]?.start ?? HEAD_HEIGHT) - HEAD_HEIGHT
  const padBottom =
    virtualizer.getTotalSize() - (virtualRows.at(-1)?.end ?? HEAD_HEIGHT)
  const canLoad = hasNextPage && !isFetchingNextPage && !isError

  // Watches the end of the list. A new callback (after each page, or a state
  // change) re-observes, and a fresh observer reports at once, so a page that
  // doesn't fill the screen loads the next one too. No effect needed: React 19
  // runs the returned cleanup when the ref changes.
  const sentinel = React.useCallback(
    (el: HTMLTableRowElement | null) => {
      if (!el || !canLoad) return
      // Nothing loaded yet: start now (the skeleton pushes this row out of view).
      if (rows.length === 0) {
        fetchNextPage()
        return
      }
      const io = new IntersectionObserver(
        ([entry]) => entry.isIntersecting && fetchNextPage(),
        { root: scroller.current, rootMargin: "0px 0px 600px 0px" }
      )
      io.observe(el)
      return () => io.disconnect()
    },
    // rows.length: re-observe after each page lands.
    [canLoad, fetchNextPage, rows.length]
  )

  const span = columns.length
  const cellClass = (meta?: ColumnDef<TData>["meta"]) =>
    cn(
      meta?.align === "end" && "text-end tabular-nums",
      meta?.hideOnMobile && "hidden @2xl/table:table-cell"
    )
  const skeletonRows = (n: number) =>
    Array.from({ length: n }, (_, i) => (
      <tr key={`skeleton-${i}`} aria-hidden>
        {columns.map((c, j) => (
          <td key={j} className={cn(CELL, cellClass(c.meta))}>
            <Skeleton
              className={cn(
                "h-4",
                c.meta?.skeleton ?? "w-20",
                c.meta?.align === "end" && "ms-auto"
              )}
            />
          </td>
        ))}
      </tr>
    ))

  const firstLoad = rows.length === 0 && (hasNextPage || isFetchingNextPage)
  if (rows.length === 0 && !hasNextPage && !isError && empty)
    return <>{empty}</>

  return (
    <div
      data-slot="infinite-table"
      className={cn("@container/table relative min-h-80", className)}
    >
      <div
        ref={scroller}
        onScroll={(e) => {
          const past = e.currentTarget.scrollTop > 400
          if (past !== scrolled) setScrolled(past)
        }}
        className={cn(
          // relative: absolutely positioned bits (sr-only text) stay inside the clip.
          "relative h-full overscroll-contain rounded-lg bg-card shadow-border",
          // First load: skeleton rows fill any height, clipped, never scrollable.
          firstLoad ? "overflow-hidden" : "overflow-auto"
        )}
      >
        <table
          // Only the rows near the viewport are in the DOM; these keep the
          // real count and position available to screen readers.
          aria-rowcount={total !== undefined ? total + 1 : -1}
          className="w-full border-separate border-spacing-0 text-sm"
        >
          <thead>
            {table.getHeaderGroups().map((group) => (
              <tr key={group.id} aria-rowindex={1}>
                {group.headers.map((header) => (
                  <th
                    key={header.id}
                    className={cn(
                      HEAD,
                      cellClass(header.column.columnDef.meta)
                    )}
                  >
                    {flexRender(
                      header.column.columnDef.header,
                      header.getContext()
                    )}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody aria-busy={isFetchingNextPage || undefined}>
            {padTop > 0 && <Spacer height={padTop} span={span} />}
            {virtualRows.map((v) => {
              const row = tableRows[v.index]
              return (
                <tr
                  key={row.id}
                  ref={virtualizer.measureElement}
                  data-index={v.index}
                  aria-rowindex={v.index + 2}
                  className="hover:bg-muted/50"
                >
                  {row.getVisibleCells().map((cell) => (
                    <td
                      key={cell.id}
                      className={cn(
                        CELL,
                        cellClass(cell.column.columnDef.meta)
                      )}
                    >
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext()
                      )}
                    </td>
                  ))}
                </tr>
              )
            })}
            {padBottom > 0 && <Spacer height={padBottom} span={span} />}

            {(firstLoad || isFetchingNextPage) && skeletonRows(firstLoad ? 40 : 3)}

            <tr ref={sentinel}>
              <td colSpan={span} className="h-14 px-3 text-center">
                {/* Announces progress; the visible copy matches. */}
                <div
                  role="status"
                  className="flex items-center justify-center gap-3 text-sm text-muted-foreground"
                >
                  {isError ? (
                    <>
                      <span>Couldn’t load more {noun.other}.</span>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => fetchNextPage()}
                      >
                        <RotateCwIcon data-icon="inline-start" />
                        Retry
                      </Button>
                    </>
                  ) : isFetchingNextPage ? (
                    <span className="sr-only">
                      Loading more {noun.other}
                    </span>
                  ) : hasNextPage ? (
                    <>
                      {total !== undefined && rows.length > 0 && (
                        <span className="tabular-nums">
                          {rows.length.toLocaleString("en-US")} of{" "}
                          {total.toLocaleString("en-US")}
                        </span>
                      )}
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => fetchNextPage()}
                      >
                        Load more
                      </Button>
                    </>
                  ) : (
                    rows.length > 0 && (
                      <span className="tabular-nums">
                        That’s all{" "}
                        {rows.length === 1
                          ? `1 ${noun.one}`
                          : `${rows.length.toLocaleString("en-US")} ${noun.other}`}
                      </span>
                    )
                  )}
                </div>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      <Button
        variant="outline"
        size="sm"
        inert={!scrolled}
        data-open={scrolled || undefined}
        onClick={() => {
          const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches
          scroller.current?.scrollTo({ top: 0, behavior: reduce ? "auto" : "smooth" })
        }}
        className="absolute top-12 left-1/2 z-20 -translate-x-1/2 -translate-y-2 rounded-full bg-popover opacity-0 shadow-popover transition-[opacity,translate] duration-150 ease-in data-open:translate-y-0 data-open:opacity-100 data-open:duration-200 data-open:ease-out motion-reduce:translate-y-0"
      >
        <ArrowUpIcon data-icon="inline-start" />
        Back to top
      </Button>
    </div>
  )
}

/** Matches `h-10` on the header and `h-11` on rows; rows are also measured. */
const HEAD_HEIGHT = 40
const ROW_HEIGHT = 44

function Spacer({ height, span }: { height: number; span: number }) {
  return (
    <tr aria-hidden>
      <td colSpan={span} style={{ height }} className="p-0" />
    </tr>
  )
}

const HEAD =
  "sticky top-0 z-10 h-10 bg-card bg-clip-padding px-3 text-start align-middle text-xs font-medium whitespace-nowrap text-muted-foreground shadow-[inset_0_-1px_var(--border)]"
const CELL = "h-11 px-3 align-middle whitespace-nowrap border-b"

export { InfiniteTable }
